#include <iostream>
#include <queue>
#include <vector>
using namespace std;

int main() {
    int n, m;
    cin >> n >> m;
    vector<vector<pair<int,int>>> g(n + 1);
    for (int i = 0; i < m; i++) {
        int u, v, w;
        cin >> u >> v >> w;
        g[u].push_back({v, w});
        g[v].push_back({u, w});
    }
    vector<int> dist(n + 1, 1e9), vis(n + 1, 0);
    dist[1] = 0;
    priority_queue<pair<int,int>, vector<pair<int,int>>, greater<pair<int,int>>> pq;
    pq.push({0, 1});
    int total = 0, cnt = 0;
    while (!pq.empty()) {
        auto [d, u] = pq.top(); pq.pop();
        if (vis[u]) continue;
        vis[u] = 1;
        total += d;
        cnt++;
        for (auto [v, w] : g[u]) {
            if (!vis[v] && w < dist[v]) {
                dist[v] = w;
                pq.push({dist[v], v});
            }
        }
    }
    if (cnt != n) cout << "not connected" << endl;
    else cout << total << endl;
    return 0;
}

#include <iostream>
#include <queue>
#include <vector>
using namespace std;

int main() {
    int n, m;
    cin >> n >> m;
    vector<vector<pair<int,int>>> g(n + 1);
    for (int i = 0; i < m; i++) {
        int a, b, c;
        cin >> a >> b >> c;
        g[b].push_back({a, c});
    }
    const int INF = 1e9;
    vector<int> dist(n + 1, INF), inQueue(n + 1, 0), cnt(n + 1, 0);
    queue<int> q;
    for (int i = 0; i <= n; i++) {
        dist[i] = 0;
        q.push(i);
        inQueue[i] = 1;
    }
    bool hasNegCycle = false;
    while (!q.empty()) {
        int u = q.front(); q.pop();
        inQueue[u] = 0;
        for (auto [v, w] : g[u]) {
            if (dist[v] > dist[u] + w) {
                dist[v] = dist[u] + w;
                if (!inQueue[v]) {
                    q.push(v);
                    inQueue[v] = 1;
                    cnt[v]++;
                    if (cnt[v] > n) { hasNegCycle = true; break; }
                }
            }
        }
        if (hasNegCycle) break;
    }
    if (hasNegCycle) cout << "no solution" << endl;
    else for (int i = 1; i <= n; i++) cout << dist[i] << " ";
    return 0;
}

