#include <iostream>
#include <vector>
using namespace std;

struct Edge { int u, v, w; };
int main() {
    int n, m, s;
    cin >> n >> m >> s;
    vector<Edge> edges(m);
    for (int i = 0; i < m; i++) cin >> edges[i].u >> edges[i].v >> edges[i].w;
    const int INF = 1e9;
    vector<int> dist(n + 1, INF);
    dist[s] = 0;
    for (int i = 0; i < n - 1; i++)
        for (auto e : edges)
            if (dist[e.u] != INF && dist[e.v] > dist[e.u] + e.w)
                dist[e.v] = dist[e.u] + e.w;
    bool hasNegCycle = false;
    for (auto e : edges)
        if (dist[e.u] != INF && dist[e.v] > dist[e.u] + e.w)
            hasNegCycle = true;
    if (hasNegCycle) cout << "has negative cycle" << endl;
    else for (int i = 1; i <= n; i++) cout << dist[i] << " ";
    return 0;
}

